package com.cpf.starter.cache.valkey;import java.time.Duration;import org.springframework.boot.context.properties.ConfigurationProperties;
@ConfigurationProperties("cpf.cache.valkey") public class CpfValkeyProperties {private boolean enabled;private String keyPrefix="cpf:";private String invalidationChannel="cpf.cache.invalidate";private Duration defaultTtl=Duration.ofMinutes(10);private boolean required=true;
 public boolean isEnabled(){return enabled;}public void setEnabled(boolean v){enabled=v;}public String getKeyPrefix(){return keyPrefix;}public void setKeyPrefix(String v){keyPrefix=v;}public String getInvalidationChannel(){return invalidationChannel;}public void setInvalidationChannel(String v){invalidationChannel=v;}public Duration getDefaultTtl(){return defaultTtl;}public void setDefaultTtl(Duration v){defaultTtl=v;}public boolean isRequired(){return required;}public void setRequired(boolean v){required=v;}public void validate(){if(!enabled)return;if(keyPrefix==null||keyPrefix.isBlank()||invalidationChannel==null||invalidationChannel.isBlank())throw new IllegalStateException("Valkey key-prefix and invalidation-channel are required");if(defaultTtl==null||defaultTtl.isNegative()||defaultTtl.isZero())throw new IllegalStateException("Valkey default-ttl must be positive");}}
